CREATE TABLE IF NOT EXISTS users(id IDENTITY PRIMARY KEY,username VARCHAR(80) NOT NULL UNIQUE,password_hash VARCHAR(300) NOT NULL,role VARCHAR(20) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash VARCHAR(64) PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id),expires_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE IF NOT EXISTS buses(id IDENTITY PRIMARY KEY,plate_number VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,capacity INT NOT NULL CHECK(capacity>0));
CREATE TABLE IF NOT EXISTS routes(id IDENTITY PRIMARY KEY,origin VARCHAR(120) NOT NULL,destination VARCHAR(120) NOT NULL,base_fare DECIMAL(12,2) NOT NULL CHECK(base_fare>0));
CREATE TABLE IF NOT EXISTS trips(id IDENTITY PRIMARY KEY,bus_id BIGINT NOT NULL REFERENCES buses(id),route_id BIGINT NOT NULL REFERENCES routes(id),departure_at TIMESTAMP WITH TIME ZONE NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'SCHEDULED');
CREATE TABLE IF NOT EXISTS bookings(id IDENTITY PRIMARY KEY,reference VARCHAR(24) NOT NULL UNIQUE,trip_id BIGINT NOT NULL REFERENCES trips(id),user_id BIGINT NOT NULL REFERENCES users(id),seat_number INT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'BOOKED',fare DECIMAL(12,2) NOT NULL,created_at TIMESTAMP WITH TIME ZONE DEFAULT CURRENT_TIMESTAMP,UNIQUE(trip_id,seat_number));
